#include <stdint.h>

extern void initialise_monitor_handles(void);

void SWDelay(uint32_t value);

int main(void)
{
	initialise_monitor_handles();

	uint32_t *pClkCtrlReg = (uint32_t*) 0x40023830;

	uint32_t *pPortCModeReg = (uint32_t*) 0x40020800;
	uint32_t *pPortCOutReg = (uint32_t*) 0x40020814;

	*pClkCtrlReg |= (1 << 2);

	*pPortCModeReg &= ~(3 << 26);
	*pPortCModeReg |= (1 << 26);

	*pPortCOutReg |= (1 << 13);

    /* Loop forever */
	while(1){
		*pPortCOutReg &= ~(1 << 13); // Active Low: ON
		SWDelay(500000);

		*pPortCOutReg |= (1 << 13); // Active Low: OFF
		SWDelay(500000);
	}
}

void SWDelay(uint32_t value){
	for(uint32_t i = 0; i < value; i++){}
}
